import random
WORDS = [b'a', b'b', b'c', b'foo', b'bar', b' ', b'  ', b'(', b')', b',', b'x1', b'\t']
def rand_line(rng, maxtok=6, words=WORDS):
    n = rng.randint(0, maxtok)
    return b''.join(rng.choice(words) for _ in range(n))
def rand_hunk(rng, maxlines=3, maxtok=6, words=WORDS, ctx=False):
    nr = rng.randint(0, maxlines); na = rng.randint(0, maxlines)
