    add = [rand_line(rng, maxtok, words) for _ in range(na)]
    lines = [b'@@ -1,%d +1,%d @@' % (nr, na)]
    lines += [b'-' + l for l in rem]
    lines += [b'+' + l for l in add]
    return b'\n'.join(lines) + b'\n', rem, add
