WS = b' \t\n\x0c\r'
def classify(b):
    if b in b' \t': return 1
    if (48 <= b <= 57) or (65 <= b <= 90) or (97 <= b <= 122) or b == 95: return 2
    return 0

def is_ws_only(content):
    return all(c in WS for c in content)

def line_layout(content):
    """content: line bytes after prefix char (with newline). returns (indent_len, tokens[(lo,hi)]) or None for ws-only"""
    if is_ws_only(content):
        return None
    i = 0
    while content[i] in WS: i += 1
    toks = []
    end = len(content)
    term = None
    if content.endswith(b'\r\n'):
        end -= 2; term = (end, len(content))
    elif content.endswith(b'\n'):
        end -= 1; term = (end, len(content))
    lo = i; kind = 0
    for hi in range(i, end):
        old = kind
        kind = classify(content[hi])
        if kind != old or old == 0:
            if lo < hi: toks.append((lo, hi))
            lo = hi
    if lo < end: toks.append((lo, end))
    if term: toks.append(term)
    return i, toks

class Side:
    def __init__(self, lines):
        # lines: list of content bytes (after prefix, with newline if present)
        self.lines = lines
        self.data = b''
        self.toks = []     # global (lo,hi)
        self.line_info = []  # (start, indent or None, first_tok_index, last_tok_index_excl)
        for l in lines:
            st = len(self.data)
            lay = line_layout(l)
            t0 = len(self.toks)
            if lay is None:
                self.line_info.append((st, None, t0, t0))
            else:
                ind, tk = lay
                for lo, hi in tk:
                    self.toks.append((st+lo, st+hi))
                self.line_info.append((st, ind, t0, len(self.toks)))
            self.data += l
    def tok(self, i):
        lo, hi = self.toks[i]
        return self.data[lo:hi]
    def seq(self):
        return [self.tok(i) for i in range(len(self.toks))]

def lcs_len(a, b):
    n, m = len(a), len(b)
    prev = [0]*(m+1)
    for i in range(n):
        cur = [0]*(m+1)
        for j in range(m):
            cur[j+1] = prev[j]+1 if a[i]==b[j] else max(prev[j+1], cur[j])
        prev = cur
    return prev[m]
