def extract_labels(out, rem_lines, add_lines):
    """Given binary output for a hunk (header + rem lines + add lines), compute per-token labels for each side.
    returns (rem_labels, add_labels) lists of booleans (True=shared), or raises."""
    ls = labels_from_output(out)[1:]
