        side = Side(side_lines)
        labels = [None]*len(side.toks)
        for li, (content, segs) in enumerate(zip(side_lines, segs_list)):
            st, ind, t0, t1 = side.line_info[li]
            if ind is None: continue
            # segs[0] is prefix (+indent)
            pos = ind  # relative position in content
            bl = {}
            for f, t in segs[1:]:
                for k in range(len(t)):
                    bl[pos+k] = f
                pos += len(t)
            # newline label: last seg face
