# parameterized middle snake
def middle_snake_p(a, b, a0, a1, b0, b1, P):
    N = a1 - a0; M = b1 - b0
    delta = N - M
    odd = delta % 2 != 0
    MAX = (N + M + 1) // 2 + 1
    off = MAX + 2
    Vf = [0] * (2 * off + 3)
    Vb = [0] * (2 * off + 3)
    ftie = P.get('ftie', '<'); btie = P.get('btie', '<')
    ge = P.get('ge', '>=')
    def fwd(d):
        ks = range(-d, d + 1, 2)
        if P.get('forder', 'asc') == 'desc': ks = reversed(ks)
        for k in ks:
            if k == -d or (k != d and ((Vf[off + k - 1] < Vf[off + k + 1]) if ftie == '<' else (Vf[off + k - 1] <= Vf[off + k + 1]))):
                x = Vf[off + k + 1]
            else:
                x = Vf[off + k - 1] + 1
            y = x - k
            xs, ys = x, y
            while x < N and y < M and a[a0 + x] == b[b0 + y]:
                x += 1; y += 1
            Vf[off + k] = x
            if odd and -(d - 1) <= k - delta <= d - 1:
                kb = delta - k
                s = Vb[off + kb] + x
                if (s >= N) if ge == '>=' else (s > N):
                    return (xs, ys, x, y, 2 * d - 1)
        return None
    def bwd(d):
        ks = range(-d, d + 1, 2)
        if P.get('border', 'asc') == 'desc': ks = reversed(ks)
        for k in ks:
            if k == -d or (k != d and ((Vb[off + k - 1] < Vb[off + k + 1]) if btie == '<' else (Vb[off + k - 1] <= Vb[off + k + 1]))):
                x = Vb[off + k + 1]
            else:
                x = Vb[off + k - 1] + 1
            y = x - k
            xs, ys = x, y
            while x < N and y < M and a[a1 - 1 - x] == b[b1 - 1 - y]:
                x += 1; y += 1
            Vb[off + k] = x
            if not odd and -d <= delta - k <= d:
                kf = delta - k
                s = x + Vf[off + kf]
                if (s >= N) if ge == '>=' else (s > N):
                    return (N - x, M - y, N - xs, M - ys, 2 * d)
        return None
    for d in range(0, MAX + 1):
        if P.get('bfirst'):
            r = bwd(d)
            if r: return r
            r = fwd(d)
            if r: return r
        else:
            r = fwd(d)
            if r: return r
            r = bwd(d)
            if r: return r
    raise Exception('no snake')

def lcs_p(a, b, P):
    out = []
    rm = P.get('rmode', 0)
    def rec(a0, a1, b0, b1):
        N = a1 - a0; M = b1 - b0
        if N <= 0 or M <= 0: return
        x, y, u, v, D = middle_snake_p(a, b, a0, a1, b0, b1, P)
        if D > 1:
            rec(a0, a0 + x, b0, b0 + y)
            for i in range(u - x): out.append((a0 + x + i, b0 + y + i))
            if (rm == 1 and u == x) or rm == 2: rec(a0 + u + 1, a1, b0 + v + 1, b1)
            else: rec(a0 + u, a1, b0 + v, b1)
        else:
            if P.get('base', 'std') == 'snake':
                for i in range(u - x): out.append((a0 + x + i, b0 + y + i))
                return
            i = a0; j = b0
            if M > N:
                while i < a1:
                    if a[i] == b[j]: out.append((i, j)); i += 1; j += 1
                    else: j += 1
            else:
                while j < b1:
                    if a[i] == b[j]: out.append((i, j)); i += 1; j += 1
                    else: i += 1
    rec(0, len(a), 0, len(b))
    return out
