from batch import *
def boundaries(strings):
    """for each string (bytes, no newline), return list of byte offsets that are token boundaries per binary"""
    cases = []; idx = []
    for s in strings:
        u = None
        try:
            u = s.decode('utf-8')
            offs = sorted(set(len(u[:i].encode()) for i in range(1, len(u))))
        except UnicodeDecodeError:
            offs = list(range(1, len(s)))
        for k in offs:
            cases.append(([s + b'\n'], [s[:k] + b'\x01' + s[k:] + b'\n']))
            idx.append((s, k))
    res = batch_labels(cases)
    out = {s: [] for s in strings}
    for (s, k), (rl, al) in zip(idx, res):
        if all(rl): out[s].append(k)
    return out
def show_tokens(s, bnds):
    parts = []; prev = 0
    for k in bnds + [len(s)]:
        parts.append(s[prev:k]); prev = k
