            out.extend_from_slice(if fg { b"\x1b[38;2;" } else { b"\x1b[48;2;" });
            push_num(out, r);
            out.push(b';');
            push_num(out, g);
            out.push(b';');
            push_num(out, b);
            out.push(b'm');
