}

fn parse_number(s: &str) -> Option<u8> {
    if let Some(rest) = s.strip_prefix("0x") {
        u8::from_str_radix(rest, 16).ok()
    } else {
        u8::from_str_radix(s, 10).ok()
    }
}

fn err_name(s: &str) -> String {
    format!(
        "unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
        s
    )
}

fn err_ansi256(s: &str) -> String {
    format!(
        "unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'",
        s
    )
}

fn err_rgb(s: &str) -> String {
    format!(
        "unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
        s
    )
}

/// Parse a color value (name, ansi256 number or rgb triple).
pub fn parse_color(s: &str) -> Result<Color, String> {
    match s.to_lowercase().as_str() {
        "black" => return Ok(Color::Black),
        "blue" => return Ok(Color::Blue),
        "green" => return Ok(Color::Green),
        "red" => return Ok(Color::Red),
        "cyan" => return Ok(Color::Cyan),
        "magenta" => return Ok(Color::Magenta),
        "yellow" => return Ok(Color::Yellow),
        "white" => return Ok(Color::White),
        _ => {}
    }
    let codes: Vec<&str> = s.split(',').collect();
    if codes.len() == 1 {
        if let Some(n) = parse_number(codes[0]) {
            Ok(Color::Ansi256(n))
        } else if s.chars().all(|c| c.is_ascii_hexdigit()) {
            Err(err_ansi256(s))
        } else {
            Err(err_name(s))
        }
    } else if codes.len() == 3 {
        let mut v = [0u8; 3];
        for (i, code) in codes.iter().enumerate() {
            match parse_number(code) {
                Some(n) => v[i] = n,
                None => return Err(err_rgb(s)),
            }
        }
        Ok(Color::Rgb(v[0], v[1], v[2]))
    } else {
        Err(err_rgb(s))
    }
}

/// The faces that can be customized from the command line.
#[derive(Clone, Debug)]
pub struct Faces {
    pub added: ColorSpec,
    pub refine_added: ColorSpec,
    pub removed: ColorSpec,
    pub refine_removed: ColorSpec,
}

impl Default for Faces {
    fn default() -> Self {
        let white = Color::Rgb(255, 255, 255);
        Faces {
            added: ColorSpec::new().with_fg(Color::Green),
            refine_added: ColorSpec::new().with_bold().with_fg(white).with_bg(Color::Green),
            removed: ColorSpec::new().with_fg(Color::Red),
            refine_removed: ColorSpec::new().with_bold().with_fg(white).with_bg(Color::Red),
        }
    }
}

const ATTRIBUTE_NAMES: &str = "foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none";

impl Faces {
    /// Apply a `--colors` argument. On error, returns the message to display.
    pub fn apply_spec(&mut self, spec: &str) -> Result<(), String> {
        let mut items = spec.split(':');
        let face_name = items.next().unwrap_or("");
        let face = match face_name {
            "added" => &mut self.added,
            "refine-added" => &mut self.refine_added,
            "removed" => &mut self.removed,
            "refine-removed" => &mut self.refine_removed,
            _ => {
                return Err(format!(
                    "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed",
                    face_name
                ))
            }
        };
        while let Some(attr) = items.next() {
            match attr {
                "foreground" | "background" => {
                    let value = match items.next() {
                        Some(v) => v,
                        None => {
                            return Err(format!(
                                "error parsing color: missing color value for face '{}'",
                                face_name
                            ))
                        }
                    };
                    let color = if value == "none" {
                        None
                    } else {
                        match parse_color(value) {
                            Ok(c) => Some(c),
                            Err(e) => return Err(format!("unexpected color value: {}", e)),
                        }
                    };
                    if attr == "foreground" {
                        face.fg = color;
                    } else {
                        face.bg = color;
                    }
                }
                "italic" => face.italic = true,
                "noitalic" => face.italic = false,
                "bold" => face.bold = true,
                "nobold" => face.bold = false,
                "dimmed" => face.dimmed = true,
                "nodimmed" => face.dimmed = false,
                "intense" => face.intense = true,
                "nointense" => face.intense = false,
                "underline" => face.underline = true,
                "nounderline" => face.underline = false,
                "none" => *face = ColorSpec::new(),
                _ => {
                    return Err(format!(
                        "unexpected attribute name: got '{}', expected {}",
                        attr, ATTRIBUTE_NAMES
                    ))
                }
            }
        }
        Ok(())
    }
}
