//! Extended grapheme cluster segmentation over arbitrary bytes.
//!
//! Invalid UTF-8 sequences (maximal invalid subparts) form clusters of their own.

use crate::tables;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Gcb {
    Cr,
    Lf,
    Control,
    Extend,
    Zwj,
    SpacingMark,
    Prepend,
    RegionalIndicator,
    Other,
}

fn in_table(table: &[(u32, u32)], c: u32) -> bool {
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = table[mid];
        if c < a {
            hi = mid;
        } else if c > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

fn gcb(c: u32) -> Gcb {
    match c {
        0x0d => Gcb::Cr,
        0x0a => Gcb::Lf,
        0x200d => Gcb::Zwj,
        0x1f1e6..=0x1f1ff => Gcb::RegionalIndicator,
        _ => {
            if c < 0x20 || (0x7f..=0x9f).contains(&c) {
                Gcb::Control
            } else if c < 0x300 {
                if c == 0xad {
                    Gcb::Control
                } else {
                    Gcb::Other
                }
            } else if in_table(tables::EXTEND, c) {
                Gcb::Extend
            } else if in_table(tables::CONTROL, c) {
                Gcb::Control
            } else if in_table(tables::SPACING_MARK, c) {
                Gcb::SpacingMark
            } else if in_table(tables::PREPEND, c) {
                Gcb::Prepend
            } else {
                Gcb::Other
            }
        }
    }
}

fn is_ext_pict(c: u32) -> bool {
    c >= 0xa9 && in_table(tables::EXTENDED_PICTOGRAPHIC, c)
}

/// Decode one UTF-8 scalar at the start of `s`.
/// Returns Ok((codepoint, len)) or Err(len of the maximal invalid subpart).
pub fn decode(s: &[u8]) -> Result<(u32, usize), usize> {
    let b0 = s[0];
    if b0 < 0x80 {
        return Ok((b0 as u32, 1));
    }
    let (need, lo2, hi2, init) = match b0 {
        0xc2..=0xdf => (1, 0x80, 0xbf, (b0 & 0x1f) as u32),
        0xe0 => (2, 0xa0, 0xbf, (b0 & 0x0f) as u32),
        0xe1..=0xec | 0xee..=0xef => (2, 0x80, 0xbf, (b0 & 0x0f) as u32),
        0xed => (2, 0x80, 0x9f, (b0 & 0x0f) as u32),
        0xf0 => (3, 0x90, 0xbf, (b0 & 0x07) as u32),
        0xf1..=0xf3 => (3, 0x80, 0xbf, (b0 & 0x07) as u32),
        0xf4 => (3, 0x80, 0x8f, (b0 & 0x07) as u32),
        _ => return Err(1),
    };
    let mut cp = init;
    for i in 1..=need {
        if i >= s.len() {
            return Err(i);
        }
        let b = s[i];
        let (lo, hi) = if i == 1 { (lo2, hi2) } else { (0x80, 0xbf) };
        if b < lo || b > hi {
            return Err(i);
        }
        cp = (cp << 6) | (b & 0x3f) as u32;
    }
    Ok((cp, need + 1))
}

/// A grapheme cluster: byte length and first code point (None if invalid UTF-8).
pub struct Cluster {
    pub len: usize,
    pub first: Option<u32>,
}

/// Find the grapheme cluster starting at the beginning of `s` (non-empty).
pub fn next_cluster(s: &[u8]) -> Cluster {
    let (c0, l0) = match decode(s) {
        Ok(x) => x,
        Err(n) => return Cluster { len: n, first: None },
    };
    let p0 = gcb(c0);
    match p0 {
        Gcb::Cr => {
            let len = if s.len() > 1 && s[1] == b'\n' { 2 } else { 1 };
            return Cluster { len, first: Some(c0) };
        }
        Gcb::Lf | Gcb::Control => return Cluster { len: l0, first: Some(c0) },
        _ => {}
    }
    let mut pos = l0;
    let mut prev = p0;
    // emoji state: 0 = none, 1 = ExtPict Extend*, 2 = ExtPict Extend* ZWJ
    let mut emoji = if is_ext_pict(c0) { 1 } else { 0 };
    let mut ri_run = if p0 == Gcb::RegionalIndicator { 1 } else { 0 };
    while pos < s.len() {
        let (c, l) = match decode(&s[pos..]) {
            Ok(x) => x,
            Err(_) => break,
        };
        let p = gcb(c);
        let ext_pict = is_ext_pict(c);
        let join = match p {
            Gcb::Cr | Gcb::Lf | Gcb::Control => false,
            _ => {
                if prev == Gcb::Prepend {
                    true
                } else if p == Gcb::Extend || p == Gcb::Zwj || p == Gcb::SpacingMark {
                    true
                } else if ext_pict && prev == Gcb::Zwj && emoji == 2 {
                    true
                } else {
                    p == Gcb::RegionalIndicator
                        && prev == Gcb::RegionalIndicator
                        && ri_run % 2 == 1
                }
            }
        };
        if !join {
            break;
        }
        // update states
        emoji = if ext_pict {
            1
        } else if emoji == 1 && p == Gcb::Extend {
            1
        } else if emoji == 1 && p == Gcb::Zwj {
            2
        } else {
            0
        };
        ri_run = if p == Gcb::RegionalIndicator { ri_run + 1 } else { 0 };
        prev = p;
        pos += l;
    }
    Cluster { len: pos, first: Some(c0) }
}
