//! Token sequence comparison (bidirectional O(ND) search with recursive splitting)
//! and partition optimization of the common subsequence.

struct Snake {
    x: isize,
    y: isize,
    u: isize,
    v: isize,
    d: isize,
}

struct Workspace {
    vf: Vec<isize>,
    vb: Vec<isize>,
}

fn middle_snake(a: &[u32], b: &[u32], ws: &mut Workspace) -> Snake {
    let n = a.len() as isize;
    let m = b.len() as isize;
    let delta = n - m;
    let odd = delta % 2 != 0;
    let max = (n + m + 1) / 2 + 1;
    let off = max + 2;
    let size = (2 * off + 3) as usize;
    ws.vf.clear();
    ws.vf.resize(size, 0);
    ws.vb.clear();
    ws.vb.resize(size, 0);
    let vf = &mut ws.vf;
    let vb = &mut ws.vb;
    let idx = |k: isize| -> usize { (off + k) as usize };
    for d in 0..=max {
        // forward pass
        let mut k = -d;
        while k <= d {
            let mut x = if k == -d || (k != d && vf[idx(k - 1)] < vf[idx(k + 1)]) {
                vf[idx(k + 1)]
            } else {
                vf[idx(k - 1)] + 1
            };
            let mut y = x - k;
            let (xs, ys) = (x, y);
            while x < n && y < m && a[x as usize] == b[y as usize] {
                x += 1;
                y += 1;
            }
            vf[idx(k)] = x;
            if odd && -(d - 1) <= k - delta && k - delta <= d - 1 {
                let kb = delta - k;
                if vb[idx(kb)] + x >= n {
                    return Snake { x: xs, y: ys, u: x, v: y, d: 2 * d - 1 };
                }
            }
            k += 2;
        }
        // backward pass (coordinates measured from the end), descending diagonals
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vb[idx(k - 1)] <= vb[idx(k + 1)]) {
                vb[idx(k + 1)]
            } else {
                vb[idx(k - 1)] + 1
            };
            let mut y = x - k;
            let (xs, ys) = (x, y);
            while x < n && y < m && a[(n - 1 - x) as usize] == b[(m - 1 - y) as usize] {
                x += 1;
                y += 1;
            }
            vb[idx(k)] = x;
            if !odd && -d <= delta - k && delta - k <= d {
                let kf = delta - k;
                if x + vf[idx(kf)] >= n {
                    return Snake { x: n - x, y: m - y, u: n - xs, v: m - ys, d: 2 * d };
                }
            }
            k -= 2;
        }
    }
    // Not reachable in practice: the searches always meet.
    Snake { x: 0, y: 0, u: 0, v: 0, d: 0 }
}

enum Task {
    Range(usize, usize, usize, usize),
    Emit(usize, usize),
}

/// Returns the indexes (in `a`) of the tokens of the computed common subsequence.
pub fn common_subsequence(a: &[u32], b: &[u32]) -> Vec<usize> {
    let mut out = Vec::new();
    let mut ws = Workspace { vf: Vec::new(), vb: Vec::new() };
    let mut stack = vec![Task::Range(0, a.len(), 0, b.len())];
    while let Some(task) = stack.pop() {
        match task {
            Task::Emit(start, len) => {
                for i in 0..len {
                    out.push(start + i);
                }
            }
            Task::Range(a0, a1, b0, b1) => {
                if a1 <= a0 || b1 <= b0 {
                    continue;
                }
                let n = a1 - a0;
                let m = b1 - b0;
                let s = middle_snake(&a[a0..a1], &b[b0..b1], &mut ws);
                if s.d > 1 {
                    let (x, y, u, v) = (s.x as usize, s.y as usize, s.u as usize, s.v as usize);
                    stack.push(Task::Range(a0 + u, a1, b0 + v, b1));
                    stack.push(Task::Emit(a0 + x, u - x));
                    stack.push(Task::Range(a0, a0 + x, b0, b0 + y));
                } else if m > n {
                    // a is a subsequence of b
                    let (mut i, mut j) = (a0, b0);
                    while i < a1 && j < b1 {
                        if a[i] == b[j] {
                            out.push(i);
                            i += 1;
                        }
                        j += 1;
                    }
                } else {
                    let (mut i, mut j) = (a0, b0);
                    while j < b1 && i < a1 {
                        if a[i] == b[j] {
                            out.push(i);
                            j += 1;
                        }
                        i += 1;
                    }
                }
            }
        }
    }
    out
}

const INF: u32 = u32::MAX / 2;

/// Choose positions in `seq` for the subsequence `lcs`, minimizing first the
/// number of shared segments, then preferring the shared part to touch the end
/// and then the start of `seq`; ties are broken by the earliest positions.
/// Returns a boolean per token of `seq` (true = shared).
pub fn optimize_partition(seq: &[u32], lcs: &[u32]) -> Vec<bool> {
    let n = seq.len();
    let m = lcs.len();
    let mut shared = vec![false; n];
    if m == 0 {
        return shared;
    }
    // earliest and latest embeddings bound the candidate positions
    let mut lo = vec![0usize; m];
    let mut j = 0usize;
    for i in 0..m {
        while seq[j] != lcs[i] {
            j += 1;
        }
        lo[i] = j;
        j += 1;
    }
    let mut hi = vec![0usize; m];
    let mut j = n - 1;
    for i in (0..m).rev() {
        while seq[j] != lcs[i] {
            j -= 1;
        }
        hi[i] = j;
        if i > 0 {
            j -= 1;
        }
    }
    // candidate windows
    let mut wstart = vec![0usize; m + 1];
    let mut pos: Vec<usize> = Vec::new();
    for i in 0..m {
        wstart[i] = pos.len();
        for jj in lo[i]..=hi[i] {
            if seq[jj] == lcs[i] {
                pos.push(jj);
            }
        }
    }
    wstart[m] = pos.len();
    let mut cost = vec![INF; pos.len()];
    // last element
    for t in wstart[m - 1]..wstart[m] {
        cost[t] = if pos[t] < n - 1 { 2 } else { 0 };
    }
    let mut suffix_min: Vec<u32> = Vec::new();
    for i in (0..m.saturating_sub(1)).rev() {
        let (ns, ne) = (wstart[i + 1], wstart[i + 2]);
        let cnt = ne - ns;
        suffix_min.clear();
        suffix_min.resize(cnt + 1, INF);
        for t in (0..cnt).rev() {
            suffix_min[t] = suffix_min[t + 1].min(cost[ns + t]);
        }
        let mut p = 0usize; // first index in next window with position > j + 1
        let mut q = 0usize; // first index in next window with position >= j + 1
        for t in wstart[i]..wstart[i + 1] {
            let jpos = pos[t];
            while p < cnt && pos[ns + p] <= jpos + 1 {
                p += 1;
            }
            while q < cnt && pos[ns + q] < jpos + 1 {
                q += 1;
            }
            let mut c = if suffix_min[p] < INF { 4 + suffix_min[p] } else { INF };
            if q < cnt && pos[ns + q] == jpos + 1 && cost[ns + q] < c {
                c = cost[ns + q];
            }
            cost[t] = c;
        }
    }
    // forward greedy selection
    let mut best = INF;
    let mut bt = usize::MAX;
    for t in wstart[0]..wstart[1] {
        if cost[t] >= INF {
            continue;
        }
        let c = (if pos[t] > 0 { 1 } else { 0 }) + cost[t];
        if c < best {
            best = c;
            bt = t;
        }
    }
    let mut prev = pos[bt];
    shared[prev] = true;
    for i in 1..m {
        let mut best = INF;
        let mut bt = usize::MAX;
        for t in wstart[i]..wstart[i + 1] {
            let jpos = pos[t];
            if jpos <= prev || cost[t] >= INF {
                continue;
            }
            let c = (if jpos == prev + 1 { 0 } else { 4 }) + cost[t];
            if c < best {
                best = c;
                bt = t;
            }
        }
        prev = pos[bt];
        shared[prev] = true;
    }
    shared
}
