//! Buffering of hunk lines, tokenization, refinement and colored output.

use std::collections::HashMap;

use crate::color::{Color, ColorSpec, Faces, RESET};
use crate::diff;
use crate::grapheme::next_cluster;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum LineKind {
    Added,
    Removed,
    Context,
    Raw,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum LineNumberStyle {
    Compact,
    Aligned,
    Fixed,
}

/// Error raised when a line number does not fit in the margin.
pub struct MarginError;

/// Marker for input on which processing never terminates.
pub struct Stuck;

const MAX_MARGIN: usize = 41;

struct Line {
    kind: LineKind,
    start: usize,
    end: usize,
}

struct LineNumbers {
    minus: u64,
    plus: u64,
    width: usize,
    full: usize,
}

pub struct Hunk {
    faces: Faces,
    warning: ColorSpec,
    default_face: ColorSpec,
    style: Option<LineNumberStyle>,
    data: Vec<u8>,
    lines: Vec<Line>,
    numbers: Option<LineNumbers>,
    margin: [u8; MAX_MARGIN],
}

fn is_ws(c: u8) -> bool {
    c.is_ascii_whitespace()
}

fn starts_escape(s: &[u8], i: usize) -> bool {
    i + 1 < s.len() && s[i] == 0x1b && s[i + 1] == b'['
}

/// Length of the complete escape sequence ("\x1b[" ... "m") starting at `i`, if any.
fn escape_len(s: &[u8], i: usize) -> Option<usize> {
    if !starts_escape(s, i) {
        return None;
    }
    s[i + 2..].iter().position(|&c| c == b'm').map(|p| p + 3)
}

/// First byte of the line after the leading escape sequences.
pub fn first_after_escape(line: &[u8]) -> Option<u8> {
    let mut i = 0;
    while let Some(l) = escape_len(line, i) {
        i += l;
    }
    line.get(i).copied()
}

/// Remove the escape sequences of `line`, appending the result to `dst`.
fn strip_escapes(line: &[u8], dst: &mut Vec<u8>) -> Result<(), Stuck> {
    let mut i = 0;
    let len = line.len();
    while i < len {
        while let Some(l) = escape_len(line, i) {
            i += l;
        }
        let start = i;
        while i < len && !starts_escape(line, i) {
            i += 1;
        }
        if i == start && i < len {
            return Err(Stuck);
        }
        dst.extend_from_slice(&line[start..i]);
    }
    Ok(())
}

/// Remove complete escape sequences, leaving incomplete ones untouched.
fn strip_escapes_lenient(line: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(line.len());
    let mut i = 0;
    while i < line.len() {
        if let Some(l) = escape_len(line, i) {
            i += l;
            continue;
        }
        out.push(line[i]);
        i += 1;
    }
    out
}

fn parse_u64(s: &[u8], i: &mut usize) -> Option<u64> {
    let start = *i;
    let mut v: u64 = 0;
    while *i < s.len() && s[*i].is_ascii_digit() {
        v = v.checked_mul(10)?.checked_add((s[*i] - b'0') as u64)?;
        *i += 1;
    }
    if *i == start {
        None
    } else {
        Some(v)
    }
}

fn parse_range(s: &[u8], i: &mut usize) -> Option<(u64, u64)> {
    let a = parse_u64(s, i)?;
    if *i < s.len() && s[*i] == b',' {
        *i += 1;
        let b = parse_u64(s, i)?;
        Some((a, b))
    } else {
        Some((a, 1))
    }
}

fn skip_ws1(s: &[u8], i: &mut usize) -> Option<()> {
    let start = *i;
    while *i < s.len() && is_ws(s[*i]) {
        *i += 1;
    }
    if *i == start {
        None
    } else {
        Some(())
    }
}

/// Parse a hunk header "@@ -a,b +c,d @@".
fn parse_hunk_header(line: &[u8]) -> Option<((u64, u64), (u64, u64))> {
    let s = strip_escapes_lenient(line);
    let mut i = 0;
    while i < s.len() && s[i] == b'@' {
        i += 1;
    }
    if i == 0 {
        return None;
    }
    skip_ws1(&s, &mut i)?;
    let mut minus = None;
    while i < s.len() && s[i] == b'-' {
        i += 1;
        let r = parse_range(&s, &mut i)?;
        skip_ws1(&s, &mut i)?;
        minus = Some(r);
    }
    let minus = minus?;
    if i >= s.len() || s[i] != b'+' {
        return None;
    }
    i += 1;
    let plus = parse_range(&s, &mut i)?;
    skip_ws1(&s, &mut i)?;
    if i >= s.len() || s[i] != b'@' {
        return None;
    }
    Some((minus, plus))
}

fn digits(x: u64) -> usize {
    if x == 0 {
        0
    } else {
        x.to_string().len()
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum TokKind {
    Other,
    Word,
    Spaces,
}

fn classify(first: Option<u32>) -> TokKind {
    match first {
        Some(0x20) | Some(0x09) => TokKind::Spaces,
        Some(c) => match char::from_u32(c) {
            Some(ch) if ch.is_alphanumeric() || ch == '_' => TokKind::Word,
            _ => TokKind::Other,
        },
        None => TokKind::Other,
    }
}

/// Split data[lo..hi] into tokens.
fn tokenize(data: &[u8], lo: usize, hi: usize, out: &mut Vec<(usize, usize)>) {
    let mut pos = lo;
    let mut tok_start = lo;
    let mut kind = TokKind::Other;
    while pos < hi {
        let cl = next_cluster(&data[pos..hi]);
        let k = classify(cl.first);
        if k != kind || kind == TokKind::Other {
            if tok_start < pos {
                out.push((tok_start, pos));
            }
            tok_start = pos;
        }
        kind = k;
        pos += cl.len;
    }
    if tok_start < hi {
        out.push((tok_start, hi));
    }
}

fn pad(out: &mut Vec<u8>, s: &str, width: usize) {
    for _ in s.len()..width {
        out.push(b' ');
    }
    out.extend_from_slice(s.as_bytes());
}

struct SideInfo {
    tokens: Vec<(usize, usize)>,
    // per line index (in hunk): (indent end, first token, one past last token) or None
    ids: Vec<u32>,
}

struct LineLayout {
    ws_only: bool,
    indent_end: usize,
    tok_lo: usize,
    tok_hi: usize,
}

impl Hunk {
    pub fn new(faces: Faces, style: Option<LineNumberStyle>) -> Self {
        Hunk {
            faces,
            warning: ColorSpec::new().with_bg(Color::Red),
            default_face: ColorSpec::new(),
            style,
            data: Vec::new(),
            lines: Vec::new(),
            numbers: None,
            margin: [0u8; MAX_MARGIN],
        }
    }

    /// Called on a hunk header line.
    pub fn start(&mut self, header: &[u8]) {
        let style = match self.style {
            Some(s) => s,
            None => return,
        };
        self.numbers = Some(match parse_hunk_header(header) {
            Some(((ms, ml), (ps, pl))) => {
                let mut width = digits(ms.wrapping_add(ml)).max(digits(ps.wrapping_add(pl)));
                if style == LineNumberStyle::Fixed {
                    width = width.max(3);
                }
                let full = if ms != 0 && ps != 0 { 2 * width + 1 } else { width };
                LineNumbers { minus: ms, plus: ps, width, full }
            }
            None => LineNumbers { minus: 0, plus: 0, width: 0, full: 0 },
        });
    }

    pub fn push(&mut self, kind: LineKind, line: &[u8]) -> Result<(), Stuck> {
        let start = self.data.len();
        strip_escapes(line, &mut self.data)?;
        let end = self.data.len();
        self.lines.push(Line { kind, start, end });
        Ok(())
    }

    fn write_tab(&self, out: &mut Vec<u8>, full: usize) {
        if self.style == Some(LineNumberStyle::Aligned) && full % 8 != 0 {
            out.push(b'\t');
        }
    }

    fn margin_context(&mut self, out: &mut Vec<u8>) {
        let ln = match &mut self.numbers {
            Some(ln) => ln,
            None => return,
        };
        let w = ln.width;
        if ln.minus == ln.plus {
            pad(out, " ", w);
        } else {
            pad(out, &ln.minus.to_string(), w);
        }
        out.push(b' ');
        pad(out, &ln.plus.to_string(), w);
        ln.minus = ln.minus.wrapping_add(1);
        ln.plus = ln.plus.wrapping_add(1);
        let full = ln.full;
        self.write_tab(out, full);
    }

    fn margin_change(&mut self, out: &mut Vec<u8>, added: bool) -> Result<(), MarginError> {
        let ln = match &mut self.numbers {
            Some(ln) => ln,
            None => return Ok(()),
        };
        let w = ln.width;
        let mut text = Vec::new();
        if added {
            if ln.minus != 0 {
                pad(&mut text, " ", w);
                text.push(b' ');
            }
            pad(&mut text, &ln.plus.to_string(), w);
        } else {
            pad(&mut text, &ln.minus.to_string(), w);
            if ln.plus != 0 {
                text.push(b' ');
                pad(&mut text, " ", w);
            }
        }
        let full = ln.full;
        if text.len() > full {
            return Err(MarginError);
        }
        if added {
            ln.plus = ln.plus.wrapping_add(1);
        } else {
            ln.minus = ln.minus.wrapping_add(1);
        }
        self.margin[..text.len()].copy_from_slice(&text);
        let face = if added { &self.faces.added } else { &self.faces.removed };
        face.write_to(out);
        out.extend_from_slice(&self.margin[..full]);
        out.extend_from_slice(RESET);
        self.write_tab(out, full);
        Ok(())
    }

    fn layout(&self, line: &Line, tokens: &mut Vec<(usize, usize)>) -> LineLayout {
        let content_start = line.start + 1;
        let content = &self.data[content_start.min(line.end)..line.end];
        let tok_lo = tokens.len();
        if content.iter().all(|&c| is_ws(c)) {
            return LineLayout { ws_only: true, indent_end: content_start, tok_lo, tok_hi: tok_lo };
        }
        let indent = content.iter().take_while(|&&c| is_ws(c)).count();
        let indent_end = content_start + indent;
        tokenize(&self.data, indent_end, line.end, tokens);
        LineLayout { ws_only: false, indent_end, tok_lo, tok_hi: tokens.len() }
    }

    /// Compute the refinement and write the whole hunk to `out`.
    pub fn process(&mut self, out: &mut Vec<u8>) -> Result<(), MarginError> {
        let result = self.process_inner(out);
        self.data.clear();
        self.lines.clear();
        result
    }

    fn process_inner(&mut self, out: &mut Vec<u8>) -> Result<(), MarginError> {
        if self.lines.is_empty() {
            return Ok(());
        }
        // layouts and tokens
        let mut rem = SideInfo { tokens: Vec::new(), ids: Vec::new() };
        let mut add = SideInfo { tokens: Vec::new(), ids: Vec::new() };
        let mut layouts: Vec<Option<LineLayout>> = Vec::with_capacity(self.lines.len());
        for line in &self.lines {
            let l = match line.kind {
                LineKind::Removed => Some(self.layout(line, &mut rem.tokens)),
                LineKind::Added => Some(self.layout(line, &mut add.tokens)),
                _ => None,
            };
            layouts.push(l);
        }
        // intern tokens
        {
            let data = &self.data;
            let mut table: HashMap<&[u8], u32> = HashMap::new();
            for side in [&mut rem, &mut add] {
                side.ids.reserve(side.tokens.len());
                for &(lo, hi) in &side.tokens {
                    let next = table.len() as u32;
                    let id = *table.entry(&data[lo..hi]).or_insert(next);
                    side.ids.push(id);
                }
            }
        }
        let common = diff::common_subsequence(&rem.ids, &add.ids);
        let lcs: Vec<u32> = common.iter().map(|&i| rem.ids[i]).collect();
        let rem_shared = diff::optimize_partition(&rem.ids, &lcs);
        let add_shared = diff::optimize_partition(&add.ids, &lcs);

        for li in 0..self.lines.len() {
            let (kind, start, end) = {
                let l = &self.lines[li];
                (l.kind, l.start, l.end)
            };
            match kind {
                LineKind::Context | LineKind::Raw => {
                    if kind == LineKind::Context {
                        self.margin_context(out);
                    }
                    let has_nl = end > start && self.data[end - 1] == b'\n';
                    let text_end = if has_nl { end - 1 } else { end };
                    self.default_face.write_to(out);
                    out.extend_from_slice(&self.data[start..text_end]);
                    out.extend_from_slice(RESET);
                    if has_nl {
                        out.push(b'\n');
                    }
                }
                LineKind::Added | LineKind::Removed => {
                    let added = kind == LineKind::Added;
                    self.margin_change(out, added)?;
                    let layout = layouts[li].as_ref().unwrap();
                    let (side, shared) = if added { (&add, &add_shared) } else { (&rem, &rem_shared) };
                    let (face, refine) = if added {
                        (&self.faces.added, &self.faces.refine_added)
                    } else {
                        (&self.faces.removed, &self.faces.refine_removed)
                    };
                    let data = &self.data;
                    let has_nl = end > start && data[end - 1] == b'\n';
                    let strip_nl = |lo: usize, hi: usize| -> &[u8] {
                        if hi > lo && data[hi - 1] == b'\n' {
                            &data[lo..hi - 1]
                        } else {
                            &data[lo..hi]
                        }
                    };
                    if layout.ws_only {
                        face.write_to(out);
                        out.extend_from_slice(&data[start..(start + 1).min(end)]);
                        out.extend_from_slice(RESET);
                        let content_start = (start + 1).min(end);
                        if content_start < end {
                            self.warning.write_to(out);
                            out.extend_from_slice(strip_nl(content_start, end));
                            out.extend_from_slice(RESET);
                        }
                    } else {
                        face.write_to(out);
                        out.extend_from_slice(&data[start..layout.indent_end]);
                        out.extend_from_slice(RESET);
                        let mut t = layout.tok_lo;
                        while t < layout.tok_hi {
                            let label = shared[t];
                            let mut u = t + 1;
                            while u < layout.tok_hi && shared[u] == label {
                                u += 1;
                            }
                            let lo = side.tokens[t].0;
                            let hi = side.tokens[u - 1].1;
                            let spec = if label {
                                face
                            } else if hi < end
                                && data[hi] == b'\n'
                                && data[lo..hi].iter().all(|&c| is_ws(c))
                            {
                                &self.warning
                            } else {
                                refine
                            };
                            spec.write_to(out);
                            out.extend_from_slice(strip_nl(lo, hi));
                            out.extend_from_slice(RESET);
                            t = u;
                        }
                    }
                    if has_nl {
                        out.push(b'\n');
                    }
                }
            }
        }
        Ok(())
    }
}

/// Write a line outside of any hunk.
pub fn output_raw(line: &[u8], out: &mut Vec<u8>) {
    let has_nl = line.last() == Some(&b'\n');
    let text = if has_nl { &line[..line.len() - 1] } else { line };
    out.extend_from_slice(RESET);
    out.extend_from_slice(text);
    out.extend_from_slice(RESET);
    if has_nl {
        out.push(b'\n');
    }
}
