//! diffr: adds word-level diff on top of unified diffs.

mod color;
mod diff;
mod grapheme;
mod help;
mod hunk;
mod tables;

use std::io::{self, BufRead, IsTerminal, Write};
use std::process;

use color::Faces;
use hunk::{first_after_escape, output_raw, Hunk, LineKind, LineNumberStyle};

const VERSION_LINE: &str = "diffr 0.1.5\n";

struct Config {
    faces: Faces,
    line_numbers: Option<LineNumberStyle>,
}

fn parse_args() -> Config {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.iter().any(|a| a == "--help") {
        print_and_exit_stdout(help::LONG_HELP, 0);
    }
    let mut config = Config { faces: Faces::default(), line_numbers: None };
    let mut i = 0;
    while i < args.len() {
        let arg = args[i].as_str();
        match arg {
            "-h" => print_and_exit_stdout(help::SHORT_HELP, 0),
            "-V" | "--version" => {
                eprint!("{}", VERSION_LINE);
                process::exit(0);
            }
            "--colors" => {
                if i + 1 >= args.len() {
                    eprintln!("option requires an argument: '--colors'");
                    process::exit(2);
                }
                i += 1;
                if let Err(msg) = config.faces.apply_spec(&args[i]) {
                    eprintln!("{}", msg);
                    process::exit(-1);
                }
            }
            "--line-numbers" => {
                if i + 1 < args.len() {
                    i += 1;
                    let style = match args[i].as_str() {
                        "compact" => LineNumberStyle::Compact,
                        "aligned" => LineNumberStyle::Aligned,
                        "fixed" => LineNumberStyle::Fixed,
                        other => {
                            eprintln!(
                                "unexpected line number style: got '{}', expected aligned|compact|fixed",
                                other
                            );
                            process::exit(-1);
                        }
                    };
                    config.line_numbers = Some(style);
                } else {
                    config.line_numbers = Some(LineNumberStyle::Compact);
                }
            }
            _ => {
                eprint!("bad argument: '{}'\n{}", arg, help::SHORT_HELP);
                process::exit(2);
            }
        }
        i += 1;
    }
    config
}

fn print_and_exit_stdout(text: &str, code: i32) -> ! {
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(text.as_bytes());
    let _ = lock.flush();
    process::exit(code);
}

enum Failure {
    Io(io::Error),
    Margin,
    Stuck,
}

impl From<io::Error> for Failure {
    fn from(e: io::Error) -> Self {
        Failure::Io(e)
    }
}

struct Output<W: Write> {
    sink: W,
    buf: Vec<u8>,
}

impl<W: Write> Output<W> {
    fn maybe_flush(&mut self) -> io::Result<()> {
        if self.buf.len() >= 1 << 16 {
            self.flush()?;
        }
        Ok(())
    }

    fn flush(&mut self) -> io::Result<()> {
        if !self.buf.is_empty() {
            self.sink.write_all(&self.buf)?;
            self.buf.clear();
        }
        self.sink.flush()
    }
}

fn run<W: Write>(config: Config, out: &mut Output<W>) -> Result<(), Failure> {
    let stdin = io::stdin();
    let mut input = io::BufReader::with_capacity(1 << 16, stdin.lock());
    let mut hunk = Hunk::new(config.faces.clone(), config.line_numbers);
    let mut in_hunk = false;
    let mut line = Vec::new();
    loop {
        line.clear();
        let n = input.read_until(b'\n', &mut line)?;
        if n == 0 {
            break;
        }
        let first = first_after_escape(&line);
        if in_hunk {
            let kind = match first {
                Some(b'+') => Some(LineKind::Added),
                Some(b'-') => Some(LineKind::Removed),
                Some(b' ') => Some(LineKind::Context),
                Some(b'\\') => Some(LineKind::Raw),
                _ => None,
            };
            match kind {
                Some(k) => {
                    if hunk.push(k, &line).is_err() {
                        return Err(Failure::Stuck);
                    }
                }
                None => {
                    if hunk.process(&mut out.buf).is_err() {
                        return Err(Failure::Margin);
                    }
                    in_hunk = false;
                }
            }
        }
        if !in_hunk {
            in_hunk = first == Some(b'@');
            if in_hunk {
                hunk.start(&line);
            }
            output_raw(&line, &mut out.buf);
        }
        out.maybe_flush()?;
    }
    if hunk.process(&mut out.buf).is_err() {
        return Err(Failure::Margin);
    }
    out.flush()?;
    Ok(())
}

fn main() {
    let config = parse_args();
    if io::stdin().is_terminal() {
        eprint!("{}", help::SHORT_HELP);
        process::exit(-1);
    }
    let stdout = io::stdout();
    let mut out = Output { sink: stdout.lock(), buf: Vec::with_capacity(1 << 17) };
    match run(config, &mut out) {
        Ok(()) => {}
        Err(Failure::Io(e)) => {
            if e.kind() == io::ErrorKind::BrokenPipe {
                process::exit(0);
            }
            let _ = out.flush();
            eprintln!("io error: {}", e);
            process::exit(-1);
        }
        Err(Failure::Margin) => {
            if let Err(e) = out.flush() {
                if e.kind() == io::ErrorKind::BrokenPipe {
                    process::exit(0);
                }
            }
            eprintln!("io error: failed to write whole buffer");
            process::exit(-1);
        }
        Err(Failure::Stuck) => {
            let _ = out.flush();
            loop {
                std::thread::sleep(std::time::Duration::from_secs(3600));
            }
        }
    }
}
