        let mut suffix = vec![INF; cnt + 1];
        for k in (0..cnt).rev() {
            suffix[k] = suffix[k + 1].min(next[k]);
        }
        let mut p = 0usize; // first index in next row with position > j + 1
        let mut q = 0usize; // first index in next row with position >= j + 1
        for &jp in cur {
            let j = jp as usize;
            while p < cnt && nxt[p] as usize <= j + 1 {
                p += 1;
            }
            while q < cnt && (nxt[q] as usize) < j + 1 {
                q += 1;
            }
            let mut c = if suffix[p] < INF { 4 + suffix[p] } else { INF };
            if q < cnt && nxt[q] as usize == j + 1 && next[q] < c {
                c = next[q];
            }
            out.push(c);
        }
    }
}

/// Choose positions in `seq` for the subsequence `lcs`, minimizing first the
/// number of shared segments, then preferring the shared part to touch the end
/// and then the start of `seq`; ties are broken by the earliest positions.
/// `nb_ids` is an upper bound of the token ids.
/// Returns a boolean per token of `seq` (true = shared).
pub fn optimize_partition(seq: &[u32], lcs: &[u32], nb_ids: usize) -> Vec<bool> {
    let n = seq.len();
    let m = lcs.len();
    let mut shared = vec![false; n];
    if m == 0 {
        return shared;
    }
    // earliest and latest embeddings bound the candidate positions
    let mut lo = vec![0usize; m];
    let mut j = 0usize;
    for i in 0..m {
        while seq[j] != lcs[i] {
            j += 1;
        }
        lo[i] = j;
        j += 1;
    }
    let mut hi = vec![0usize; m];
    let mut j = n - 1;
    for i in (0..m).rev() {
        while seq[j] != lcs[i] {
            j -= 1;
        }
        hi[i] = j;
        if i > 0 {
            j -= 1;
        }
    }
    let mut occ: Vec<Vec<u32>> = vec![Vec::new(); nb_ids];
    for (p, &id) in seq.iter().enumerate() {
        occ[id as usize].push(p as u32);
    }
    let mut range = Vec::with_capacity(m);
    for t in 0..m {
        let list = &occ[lcs[t] as usize];
        let a = list.partition_point(|&p| (p as usize) < lo[t]);
        let b = list.partition_point(|&p| (p as usize) <= hi[t]);
        range.push((a as u32, b as u32));
    }
    let rows = Rows { seq_len: n, occ: &occ, lcs, range };

    // backward pass keeping checkpoints
    let nb_blocks = (m + CHECKPOINT - 1) / CHECKPOINT;
    let mut checkpoints: Vec<Vec<u32>> = vec![Vec::new(); nb_blocks + 1];
    let mut cur: Vec<u32> = Vec::new();
    let mut next: Vec<u32> = Vec::new();
    for t in (0..m).rev() {
        rows.compute(t, &next, &mut cur);
        if t % CHECKPOINT == 0 {
            checkpoints[t / CHECKPOINT] = cur.clone();
        }
        std::mem::swap(&mut cur, &mut next);
    }

    // forward greedy selection, block by block
    let mut block_rows: Vec<Vec<u32>> = Vec::new();
    let mut prev: Option<usize> = None;
    for blk in 0..nb_blocks {
        let t0 = blk * CHECKPOINT;
        let t1 = (t0 + CHECKPOINT).min(m);
        // recompute rows t0..t1
        block_rows.resize(t1 - t0, Vec::new());
        let mut next_row: Vec<u32> = if t1 < m { checkpoints[t1 / CHECKPOINT].clone() } else { Vec::new() };
        for t in (t0..t1).rev() {
