            rows.compute(t, &next_row, &mut row);
            next_row = row.clone();
            block_rows[t - t0] = row;
        }
        for t in t0..t1 {
            let costs = &block_rows[t - t0];
            let positions = rows.positions(t);
            let mut best = INF;
            let mut bp = usize::MAX;
            for (k, &pp) in positions.iter().enumerate() {
